package com.jgeted.sagadyssey.core.structure;
import com.jgeted.sagadyssey.Sagadyssey;
import com.jgeted.sagadyssey.social.combat.*;
import com.jgeted.sagadyssey.social.household.*;
import com.jgeted.sagadyssey.social.life.*;
import com.jgeted.sagadyssey.social.needs.*;
import com.jgeted.sagadyssey.social.politics.*;
import com.jgeted.sagadyssey.worldsim.lod.*;
import com.jgeted.sagadyssey.worldsim.rights.*;
import com.jgeted.sagadyssey.worldsim.transfer.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.world.Container;
import net.minecraft.world.item.Items;
import java.util.*;
public final class SocietyConflictGameTests {
 private static int count(Container c){return SupplyFlowService.count(c,new ItemFingerprint("minecraft:carrot",0));}
 private static void withdraw(GameTestHelper h,NaturalVillageBuilding b,int quantity){var s=h.getLevel().getServer();var n=NaturalVillageR1GameTests.actor(h.getLevel(),b,0);var source=NaturalPolityData.inventory(s,b,1);UUID from=NaturalVillageEconomyData.storeId(b,1),to=ContainerIds.npcPersonal(n.getCharacterId());var r=RightsStateData.get(s);var req=new TransferRequest(UUID.randomUUID(),SubjectRef.household(NaturalVillageLifeData.home(b)),TransferIntent.GIFT,List.of(new TransferLeg(from,to,new ItemFingerprint("minecraft:carrot",0),quantity)),List.of(new ExpectedRevision(from,r.context(from).revision()),new ExpectedRevision(to,r.context(to).revision())),"controlled emergency household allocation, still physical private food",h.getLevel().getGameTime());h.assertTrue(new TransferService(r,TransferLedgerData.get(s)).submit(req,Map.of(from,new TransferEndpoint(from,source),to,new TransferEndpoint(to,n.getPersonalInventory())),h.getLevel().getGameTime()).successful(),"emergency allocation moves the real stock, without deleting it");}
 public static void run(GameTestHelper h){var l=h.getLevel();var s=l.getServer();var seller=NaturalVillageR1GameTests.fixture(h,0,NaturalVillageLayout.FARM_V2);var buyer=NaturalVillageR1GameTests.fixture(h,96,NaturalVillageLayout.WOOD_V2);int[] stage={0},last={-1};long[] stopped={0};UUID[] deal={null};
  h.onEachTick(()->{if(last[0]==s.getTickCount())return;last[0]=s.getTickCount();var ex=SettlementExchangeData.get(s);var wars=NaturalConflictData.get(s);
   if(s.getTickCount()%4000==0)Sagadyssey.LOGGER.info("R3_CONFLICT_PROGRESS stage={} trade={} conflict={}",stage[0],ex.deals().stream().map(t->t.getString("State")+":"+t.getInt("FoodOwed")).toList(),wars.disputes().stream().map(t->t.getString("State")+":"+t.getString("Reason")+":"+t.getBoolean("Returning")).toList());
   if(stage[0]==0&&h.getTick()>=500){if(SupplyFlowService.count(NaturalPolityData.inventory(s,buyer,2),new ItemFingerprint("minecraft:oak_log",0))<2)return;for(var b:List.of(seller,buyer))for(int i:new int[]{0,2})NaturalVillageR1GameTests.actor(l,b,i).setNoAi(true);NaturalVillageR1GameTests.actor(l,seller,1).setNoAi(true);var n=NaturalVillageR1GameTests.actor(l,seller,0);NaturalVillageR3GameTests.gift(h,n.getCharacterId(),ContainerIds.npcPersonal(n.getCharacterId()),n.getPersonalInventory(),NaturalVillageEconomyData.storeId(seller,1),NaturalPolityData.inventory(s,seller,1),"carrot",16);for(int i:new int[]{0,2})NpcLifeData.get(s).setHunger(NaturalVillageLifeData.person(buyer,i),950,l.getGameTime());NpcLifeData.get(s).setHunger(NaturalVillageLifeData.person(buyer,1),850,l.getGameTime());stage[0]=1;}
   if(stage[0]==1){var t=ex.deals().stream().filter(d->d.hasUUID("PayRoute")&&SupplyFlowData.get(s).route(d.getUUID("PayRoute")).stage()==SupplyFlowData.Stage.CARRYING).findFirst().orElse(null);if(t==null)return;deal[0]=t.getUUID("Id");withdraw(h,seller,14);h.assertTrue(count(NaturalPolityData.inventory(s,seller,1))==2,"seller cannot satisfy four promised food after real emergency allocation");stage[0]=2;}
   if(stage[0]==2){var t=ex.deals().stream().filter(d->d.getUUID("Id").equals(deal[0])).findFirst().orElseThrow();if(t.getInt("FoodOwed")!=4)return;NaturalVillageR1GameTests.actor(l,buyer,1).setNoAi(true);if(l.getGameTime()-t.getLong("Created")<24200)return;
    var n=NaturalVillageR1GameTests.actor(l,buyer,0);NaturalVillageR3GameTests.gift(h,n.getCharacterId(),ContainerIds.npcPersonal(n.getCharacterId()),n.getPersonalInventory(),NaturalVillageEconomyData.storeId(buyer,1),NaturalPolityData.inventory(s,buyer,1),"carrot",2);
    h.assertTrue(!wars.respond(s,deal[0],UUID.randomUUID()).equals("ACTIVE"),"unrelated player/person cannot authorize conflict");h.assertTrue(!wars.respond(s,deal[0],NaturalVillageLifeData.person(buyer,1)).equals("ACTIVE"),"unavailable original volunteers cannot be replaced with an invented army");
    for(var b:List.of(seller,buyer))NaturalVillageR1GameTests.actor(l,b,2).setNoAi(false);String response=wars.respond(s,deal[0],NaturalVillageLifeData.person(buyer,1));h.assertTrue(response.equals("ACTIVE"),"verified prepaid debt and actual participants/rations: "+response);h.assertTrue(count(NaturalPolityData.inventory(s,seller,1))==0&&count(NaturalPolityData.inventory(s,buyer,1))==0,"both sides really spend their two rations");NaturalVillageR1GameTests.visiting(l,seller,false);NaturalVillageR1GameTests.visiting(l,buyer,false);stage[0]=3;if(NaturalVillageR3GameTests.phase().equals("r3-withdraw")){NaturalConflictData.actor(s,buyer).setCommand(com.jgeted.sagadyssey.npc.entity.NpcCommand.STAY);stage[0]=6;}
   }
   if(stage[0]==6){var t=wars.disputes().getFirst();if(!t.getString("State").equals("CEASEFIRE"))return;var n=NaturalConflictData.actor(s,buyer);h.assertTrue(!t.getBoolean("Returning")&&t.contains("PositionAtWithdrawalA")&&t.getInt("ConsumedCarrots")==4&&n!=null&&n.getCharacterId().equals(NaturalVillageLifeData.person(buyer,2))&&n.getTarget()==null,"explicit withdrawal ends hostile and return assignments, preserving original person, actual position and spent supplies");h.assertTrue(ex.deals().stream().anyMatch(d->d.getUUID("Id").equals(deal[0])&&d.getInt("FoodOwed")==4),"withdrawal never refunds rations or forgives the prepaid debt");Sagadyssey.LOGGER.info("R3_AUTHORITY_WITHDRAWAL_ACCEPT originalPeople=true rations=4 debt=4 fictitiousReturn=false hostileTask=false");h.succeed();stage[0]=5;}
   if(stage[0]==3){var t=wars.disputes().getFirst();if(!t.getString("State").equals("CEASEFIRE")||t.getBoolean("Returning"))return;var encounter=CombatEncounterData.get(s).encounter(t.getUUID("Encounter"));h.assertTrue(t.getInt("ConsumedCarrots")==4&&t.getInt("Wounds")+t.getInt("Deaths")>0&&encounter.status()==EncounterStatus.ENDED,"real injury/death terminates the actual encounter, beyond a relation score change");h.assertTrue(ex.deals().stream().filter(d->d.getUUID("Id").equals(deal[0])).findFirst().orElseThrow().getInt("FoodOwed")==4,"ceasefire does not erase original unpaid obligations");stopped[0]=l.getGameTime();stage[0]=4;}
   if(stage[0]==4&&l.getGameTime()-stopped[0]>=1000){var t=wars.disputes().getFirst();h.assertTrue(wars.respond(s,deal[0],NaturalVillageLifeData.person(buyer,1)).equals("CEASEFIRE")&&t.getInt("ConsumedCarrots")==4,"old provocation cannot rearm after ceasefire");NaturalVillageR3GameTests.checkpoint(h,List.of(buyer,seller));Sagadyssey.LOGGER.info("R3_CONFLICT_ACCEPT originalParticipants=2 rationsConsumed=4 wounds={} deaths={} originalDebt=4 returned=true ceasefire=true",t.getInt("Wounds"),t.getInt("Deaths"));h.succeed();stage[0]=5;}
  });
 }
 public static void restart(GameTestHelper h){var l=h.getLevel();var s=l.getServer();var villages=NaturalVillageR3GameTests.restored(h);long start=l.getGameTime();int[] last={-1};h.onEachTick(()->{if(last[0]==s.getTickCount())return;last[0]=s.getTickCount();if(l.getGameTime()-start<48200)return;var wars=NaturalConflictData.get(s);var t=wars.disputes().getFirst();var encounter=CombatEncounterData.get(s).encounter(t.getUUID("Encounter"));h.assertTrue(t.getString("State").equals("CEASEFIRE")&&!t.getBoolean("Returning")&&t.getInt("ConsumedCarrots")==4&&encounter.status()==EncounterStatus.ENDED&&wars.respond(s,t.getUUID("Id"),NaturalVillageLifeData.person(villages.getFirst(),1)).equals("CEASEFIRE"),"independent restart and expired minimum treaty duration never restart an old action or respend rations");
   var a=NaturalConflictData.actor(s,villages.getFirst());var b=NaturalConflictData.actor(s,villages.getLast());if(a!=null&&b!=null&&a.isAlive()&&b.isAlive()){float hp=b.getHealth();int wounds=InjuryData.get(s).wounds().size();b.hurt(l.damageSources().mobAttack(a),4);h.assertTrue(b.getHealth()==hp&&InjuryData.get(s).wounds().size()==wounds,"late hostile damage is rejected after ceasefire, including persisted incoming action");}h.assertTrue(SettlementExchangeData.get(s).deals().stream().anyMatch(d->d.getUUID("Id").equals(t.getUUID("Id"))&&d.getInt("FoodOwed")==4),"war and reload retain the real four-food debt");Sagadyssey.LOGGER.info("R3_CONFLICT_RESTART_ACCEPT treatyTicks={} sameParticipants=true rations=4 noRepeatedDamage=true originalDebt=4",l.getGameTime()-start);h.succeed();});}
}
